bash: mkdir -p /tmp/klee_test && cat > /tmp/klee_test/test.c << 'EOF'
#include <klee/klee.h>
#include <stdio.h>

int main() {
    int x;
    klee_make_symbolic(&x, sizeof(x), "x");
    if (x > 0) {
        printf("x is positive\n");
    } else {
        printf("x is non-positive\n");
    }
    return 0;
}
EOF
clang-16 -I/usr/local/include -c /tmp/klee_test/test.c -o /tmp/klee_test/test.bc 2>&1

